// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address target, uint256 value) public {
        vm.assume(caller != c.owner());
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter >= balanceBefore);
    }
}

